41	std::vector<int> MCFM::ID(size_t id)
42	{
43	  std::vector<int> ids;
44	  for (size_t n(0);id>0;++n) {
45	    if (id&(1<<n)) {
46	      ids.push_back(n);
47	      id-=1<<n;
48	    }
49	  }
50	  return ids;
51	}
