78	Process::Process(const std::vector<Leg> &legs,int is1,int is2):
79	  m_legs(legs) {
80	  m_is[0]=is1;
81	  m_is[1]=is2;
82	  m_sf=ISSymmetryFactor(m_legs,0);
83	  m_sf*=FSSymmetryFactor(m_legs,0);
84	  m_cfac=ISSymmetryFactor(m_legs,1);
85	  m_cfac*=FSSymmetryFactor(m_legs,1);
86	  m_bfac=0.;
87	  for (size_t i(0);i<m_legs.size();++i)
88	    if (m_legs[i].Mass()==0.0) {
89	      if (abs(m_legs[i].Strong())==3) m_bfac+=4./3.;
90	      else if (m_legs[i].Strong()==8) m_bfac+=3.;
91	    }
92	  p_p = new double[4*mxpart_mod::mxpart];
93	  p_msqv = new double[(2*nf_mod::nf+1)*(2*nf_mod::nf+1)];
