101	double Process::GetSchemeFactor(int scheme,int mode) {
102	  int myscheme(GetScheme());
103	  if (scheme==myscheme) return 0.;
104	  double factor(0.0);
105	  for (size_t i(0);i<m_legs.size();++i)
106	    if (m_legs[i].Mass()==0.0) {
107	      if (abs(m_legs[i].Strong())==3) factor+=.5*4./3.;
108	      else if (m_legs[i].Strong()==8) factor+=3./6.;
109	    }
110	  if (mode==1) factor*=qcdcouple_mod::ason2pi;
111	  if (scheme==0 && myscheme==1) return factor;
112	  if (scheme==1 && myscheme==0) return -factor;
113	  return sqrt(-1.);
114	}
