116	double Process::ISSymmetryFactor(const std::vector<Leg> &legs,
117					 const int mode) const {
118	  double issf(1.);
119	  if (mode==0) {
120	    for (size_t i(0);i<legs.size();++i)
121	      if (legs[i].m_is) {
122		if (legs[i].IsFermion()) issf*=2.;
123		if (legs[i].IsVector()) issf*=legs[i].Mass()?3.:2.;
124		if (legs[i].Strong()) issf*=abs(legs[i].Strong());
125	      }
126	  }
127	  else {
128	    for (size_t i(0);i<2;++i) {
129	      if (legs[m_is[i]].IsFermion()) issf*=2.;
130	      if (legs[m_is[i]].IsVector()) issf*=legs[m_is[i]].Mass()?3.:2.;
131	      if (legs[m_is[i]].Strong()) issf*=abs(legs[m_is[i]].Strong());
132	    }
133	  }
134	  return issf;
135	}
