139	double Process::FSSymmetryFactor(const std::vector<Leg> &legs,
140					 const int mode) const {
141	  std::vector<int> count(50,0);
142	  if (mode==0) {
143	    for (size_t i(0);i<m_legs.size();++i)
144	      if (!legs[i].m_is) ++count[legs[i].m_fl+24];
145	  }
146	  else {
147	    for (size_t i(0);i<m_legs.size();++i)
148	      if (i!=m_is[0] && i!=m_is[1]) ++count[legs[i].m_fl+24];
149	  }
150	  double fssf(1.);
151	  for (size_t i(0);i<count.size();++i) fssf*=factorial(count[i]);
152	  return fssf;
153	}
