321	bool CXX_Interface::CheckInput(std::map<std::string,std::string>& parameters) {
322	
323	  // All lepton masses and widths should be zero. (Except tau?)
324	  if (ToType<double>(ReadParam("electron_mass", parameters)) > 0.) return false;
325	  if (ToType<double>(ReadParam("muon_mass", parameters)) > 0.) return false;
326	  //if (ToType<double>(ReadParam("tau_mass", parameters)) > 0.) return false;
327	  //if (ToType<double>(ReadParam("tau_width", parameters)) > 0.) return false;
328	
329	  // All quarks (except top and bottom) massless.
330	  if (ToType<double>(ReadParam("down_mass", parameters)) > 0.) return false;
331	  if (ToType<double>(ReadParam("up_mass", parameters)) > 0.) return false;
332	  if (ToType<double>(ReadParam("strange_mass", parameters)) > 0.) return false;
333	  if (ToType<double>(ReadParam("charm_mass", parameters)) > 0.) return false;
334	  // if (ToType<double>(ReadParam("bottom_mass", parameters)) > 0.) return false;
335	
336	  // TODO: could check consistency of EW parameters here.
337	
338	  return true;
339	}
